{ pkgs ? import <nixpkgs> {} }:

{
  description = "Development shell for React repository";

  imports = [
    pkgs.nodejs-build
  ];

  buildInputs = [
    pkgs.nodejs_20
    pkgs.yarn
    pkgs.rustCargo
    pkgs.python3
    pkgs.git
    pkgs.coreutils
    pkgs.bash
    pkgs.gcc
    pkgs.gnumake
    pkgs.pkg-config
  ];

  shellAliases = {
    node = "nodejs";
    yarn-install = "yarn install";
    build = "yarn build";
    test = "yarn test";
  };
}
